// Package provision implements MCP access provisioning (board T-014,
// SPEC §9): the daemon generates the HTTP-MCP bearer token at bootstrap,
// injects it into the container via the compose profile's ${IOWAP_MCP_BEARER}
// interpolation, shows it exactly once in the web UI together with ready-made
// agent config snippets — and keeps only a SHA-256 hash afterwards.
package provision

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
)

// BearerPrefix marks tokens generated by the daemon.
const BearerPrefix = "iw_mcp_"

// BridgeTokenPrefix marks bridge tokens generated by the daemon (v0.1.1
// auto-provisioning); distinct from BearerPrefix so the two token kinds
// never collide.
const BridgeTokenPrefix = "iw_br_"

// GenerateBearer returns a fresh random bearer token: the "iw_mcp_" prefix
// followed by 32 bytes of crypto/rand encoded as unpadded base64url
// (43 characters, 256 bit entropy).
func GenerateBearer() (string, error) {
	return generateToken(BearerPrefix)
}

// GenerateBridgeToken returns a fresh random bridge token — same crypto/rand
// logic as GenerateBearer, under the "iw_br_" prefix (v0.1.1: the daemon
// generates the bridge token itself on fresh installs instead of demanding
// IOWAP_BRIDGE_TOKEN from the user).
func GenerateBridgeToken() (string, error) {
	return generateToken(BridgeTokenPrefix)
}

func generateToken(prefix string) (string, error) {
	buf := make([]byte, 32)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("generating token: %w", err)
	}
	return prefix + base64.RawURLEncoding.EncodeToString(buf), nil
}

// HashBearer returns the hex SHA-256 of the full bearer token — the only
// thing the daemon keeps after the one-time display.
func HashBearer(bearer string) string {
	sum := sha256.Sum256([]byte(bearer))
	return hex.EncodeToString(sum[:])
}
